column62:
Always had a fondness for this FizzBuzz in Perl...<p><pre><code>    use List::Enumerator qw/E/;

    my $fizzbuzz =
        E(1)->countup
            ->zip(
                E("", "", "Fizz")->cycle,
                E("", "", "", "", "Buzz")->cycle
            )
            ->map( sub {
                my ($n, $fizz, $buzz) = @$_;
                $fizz . $buzz || $n;
            });

    $fizzbuzz->take(20)->each(sub {
        say $_;
    });</code></pre>
